# 30_tables.R: summary tables for the sampling-requirement simulation (both the metacommunity and the known-parameter experiments). No replicate is dropped or selected on results; unsupported contrasts are counted explicitly.
# Accuracy rule fixed before inspecting results: a contrast estimate is "accurate" when |estimate - truth| <= max(1 pp, 25% of |truth|) (response scale; pp = percentage points of dissimilarity); sensitivity: (0.5 pp, 15%) and (2 pp, 50%).
suppressMessages({library(dplyr); library(tidyr)}); T <- "revision_sampling/tables"
ACC <- list(primary = c(1, .25), strict = c(.5, .15), lenient = c(2, .5)); acc <- function(err, tr, rule) abs(err) <= pmax(rule[1], rule[2] * abs(tr))
for (SIM in c("meta", "known")) {
  sup <- read.csv(file.path(T, sprintf("sim_%s_sup.csv", SIM))); fit <- read.csv(file.path(T, sprintf("sim_%s_fit.csv", SIM))); con <- read.csv(file.path(T, sprintf("sim_%s_con.csv", SIM)))
  sup$reason[is.na(sup$reason)] <- "not evaluated"; tn <- read.csv(file.path(T, sprintf("sim_%s_testnull.csv", SIM))); fit <- fit %>% left_join(tn, by = c("n_sites", "env", "rep", "order")) %>% mutate(skill_total = 1 - (rmse_total_pp / 100)^2 / test_var_total); con <- con %>% mutate(across(c(dT, dO, dH), ~ .x), err_dT = dT - true_dT, err_dO = dO - true_dO, err_dH = dH - true_dH, acc_dT = acc(err_dT, true_dT, ACC$primary), acc_dO = acc(err_dO, true_dO, ACC$primary), acc_dH = acc(err_dH, true_dH, ACC$primary),
      acc_dT_strict = acc(err_dT, true_dT, ACC$strict), acc_dT_lenient = acc(err_dT, true_dT, ACC$lenient), rel_err_dT = ifelse(abs(true_dT) >= 1, err_dT / abs(true_dT), NA_real_), sign_ok_dT = sign(dT) == sign(true_dT) | abs(true_dT) < 1)
  if (SIM == "known") con <- con %>% mutate(err_link_T = dEtaT - true_dEtaT, err_link_S = dEtaS - true_dEtaS)
  write.csv(con, file.path(T, sprintf("sim_%s_contrast_errors.csv", SIM)), row.names = FALSE)
  # availability (every replicate counted; unsupported = FALSE)
  av <- function(d, by) d %>% group_by(across(all_of(by))) %>% summarise(n_units = n(), supported_fraction = mean(supported), n_supported = sum(supported), median_n_ref_supported = median(n_ref_supported[supported], na.rm = TRUE), median_interval_width = median(interval_width[supported], na.rm = TRUE),
      median_max_common_profiles = median(max_common_profiles), median_combos = median(n_combos), median_sites_used = median(n_sites_used), .groups = "drop")
  S <- sup %>% filter(in_S); Cs <- sup %>% filter(in_C); Fs <- sup %>% filter(in_F)
  write.csv(av(S, c("env", "sampler", "n_sites", "order")), file.path(T, sprintf("sim_%s_availability_sites.csv", SIM)), row.names = FALSE); write.csv(av(Cs, c("env", "sampler", "n_combos_target", "order")), file.path(T, sprintf("sim_%s_availability_combinations.csv", SIM)), row.names = FALSE)
  write.csv(av(Fs, c("env", "sampler", "n_sites", "n_combos_target")), file.path(T, sprintf("sim_%s_availability_factorial_k5.csv", SIM)), row.names = FALSE)
  write.csv(sup %>% filter(in_S | in_C | in_F) %>% count(sampler, env, order, reason) %>% group_by(sampler, env, order) %>% mutate(share = n / sum(n)) %>% ungroup(), file.path(T, sprintf("sim_%s_unsupported_reasons.csv", SIM)), row.names = FALSE)
  # accuracy among supported contrasts, success counting unsupported as failure
  acs <- function(d, supd, by_con, by_sup) { tot <- supd %>% group_by(across(all_of(by_sup))) %>% summarise(n_units = n(), n_supported_units = sum(supported), .groups = "drop")
    a <- d %>% group_by(across(all_of(c(by_con, "model", "contrast")))) %>% summarise(n_est = n(), median_abs_err_dT = median(abs(err_dT)), median_err_dT = median(err_dT), median_abs_err_dO = median(abs(err_dO)), median_abs_err_dH = median(abs(err_dH)), median_true_dT = median(true_dT), median_abs_true_dT = median(abs(true_dT)),
      median_rel_err_dT = median(rel_err_dT, na.rm = TRUE), accurate_dT = mean(acc_dT), accurate_dO = mean(acc_dO), accurate_dH = mean(acc_dH), accurate_dT_strict = mean(acc_dT_strict), accurate_dT_lenient = mean(acc_dT_lenient), sign_correct_dT = mean(sign_ok_dT), n_accurate_dT = sum(acc_dT),
      rmse_dT = sqrt(mean(err_dT^2)), { if (SIM == "known") tibble(median_abs_err_link_T = median(abs(err_link_T)), median_err_link_T = median(err_link_T), rmse_link_T = sqrt(mean(err_link_T^2))) else tibble() }, .groups = "drop")
    left_join(a, tot, by = setNames(by_sup, by_con)) %>% mutate(success_dT_all_units = n_accurate_dT / n_units) }
  byc <- c("env", "sampler", "n_sites", "order"); byS <- c("env", "sampler", "n_sites", "order"); write.csv(acs(con %>% filter(in_S), S, byc, byS), file.path(T, sprintf("sim_%s_accuracy_sites.csv", SIM)), row.names = FALSE)
  write.csv(acs(con %>% filter(in_C), Cs, c("env", "sampler", "n_combos_target", "order"), c("env", "sampler", "n_combos_target", "order")), file.path(T, sprintf("sim_%s_accuracy_combinations.csv", SIM)), row.names = FALSE)
  write.csv(acs(con %>% filter(in_F), Fs, c("env", "sampler", "n_sites", "n_combos_target"), c("env", "sampler", "n_sites", "n_combos_target")), file.path(T, sprintf("sim_%s_accuracy_factorial_k5.csv", SIM)), row.names = FALSE)
  # prediction (Q2): held-out deviance explained and RMSE; additive minus spread-only
  hs <- function(d, by) { w <- d %>% select(all_of(c(by, "rep", "model", "D2_total", "rmse_total_pp", "rmse_occupancy_pp", "rmse_heterogeneity_pp", "converged", "skill_total", if (SIM == "known") "D2_total_oracle"))) %>% pivot_wider(names_from = model, values_from = c(D2_total, rmse_total_pp, rmse_occupancy_pp, rmse_heterogeneity_pp, converged, skill_total))
    w %>% group_by(across(all_of(by))) %>% summarise(n_fits = n(), D2_additive = median(D2_total_additive, na.rm = TRUE), D2_spread_only = median(D2_total_spread_only, na.rm = TRUE), D2_gain_median = median(D2_total_additive - D2_total_spread_only, na.rm = TRUE), D2_gain_positive = mean((D2_total_additive - D2_total_spread_only) > 0, na.rm = TRUE), skill_additive = median(skill_total_additive, na.rm = TRUE), skill_spread_only = median(skill_total_spread_only, na.rm = TRUE), skill_gain_median = median(skill_total_additive - skill_total_spread_only, na.rm = TRUE), skill_gain_positive = mean((skill_total_additive - skill_total_spread_only) > 0, na.rm = TRUE),
      rmse_total_pp_additive = median(rmse_total_pp_additive, na.rm = TRUE), rmse_total_pp_spread_only = median(rmse_total_pp_spread_only, na.rm = TRUE), rmse_occ_pp_additive = median(rmse_occupancy_pp_additive, na.rm = TRUE), rmse_het_pp_additive = median(rmse_heterogeneity_pp_additive, na.rm = TRUE), conv_additive = mean(converged_additive, na.rm = TRUE),
      D2_share_of_oracle = if (SIM == "known") median(D2_total_additive / D2_total_oracle, na.rm = TRUE) else NA_real_, .groups = "drop") }
  write.csv(hs(fit %>% filter(in_S), c("env", "sampler", "n_sites", "order")), file.path(T, sprintf("sim_%s_prediction_sites.csv", SIM)), row.names = FALSE); write.csv(hs(fit %>% filter(in_C), c("env", "sampler", "n_combos_target", "order")), file.path(T, sprintf("sim_%s_prediction_combinations.csv", SIM)), row.names = FALSE)
  write.csv(hs(fit %>% filter(in_F), c("env", "sampler", "n_sites", "n_combos_target")), file.path(T, sprintf("sim_%s_prediction_factorial_k5.csv", SIM)), row.names = FALSE)
  # paired balanced - random (same sites, same communities, same target number of combinations)
  u <- c("n_sites", "env", "rep", "order", "n_combos_target"); P <- sup %>% select(all_of(u), sampler, supported, n_ref_supported, interval_width, n_combos, n_sites_used) %>% pivot_wider(names_from = sampler, values_from = c(supported, n_ref_supported, interval_width, n_combos, n_sites_used))
  P <- P %>% mutate(pattern = case_when(supported_random & supported_balanced ~ "both supported", !supported_random & supported_balanced ~ "balanced only", supported_random & !supported_balanced ~ "random only", TRUE ~ "neither")); write.csv(P, file.path(T, sprintf("sim_%s_paired_units.csv", SIM)), row.names = FALSE)
  write.csv(P %>% group_by(env, order, n_sites) %>% summarise(n_units = n(), random_supported = mean(supported_random), balanced_supported = mean(supported_balanced), balanced_only = mean(pattern == "balanced only"), random_only = mean(pattern == "random only"), both = mean(pattern == "both supported"), neither = mean(pattern == "neither"), .groups = "drop"), file.path(T, sprintf("sim_%s_paired_availability.csv", SIM)), row.names = FALSE)
  both <- con %>% filter(model == "additive") %>% select(all_of(u), sampler, contrast, err_dT, true_dT, acc_dT) %>% pivot_wider(names_from = sampler, values_from = c(err_dT, true_dT, acc_dT)) %>% filter(!is.na(err_dT_random), !is.na(err_dT_balanced))
  write.csv(both %>% group_by(contrast, order) %>% summarise(n_pairs = n(), median_abs_err_random = median(abs(err_dT_random)), median_abs_err_balanced = median(abs(err_dT_balanced)), median_paired_diff_abs_err = median(abs(err_dT_balanced) - abs(err_dT_random)), balanced_better = mean(abs(err_dT_balanced) < abs(err_dT_random)), accurate_random = mean(acc_dT_random), accurate_balanced = mean(acc_dT_balanced), .groups = "drop"), file.path(T, sprintf("sim_%s_paired_accuracy.csv", SIM)), row.names = FALSE)
  # pooled pairs excluding unsupported: balanced vs random held-out D2 (same test sites)
  fp <- fit %>% filter(model == "additive") %>% select(all_of(u), sampler, D2_total, rmse_total_pp, skill_total) %>% pivot_wider(names_from = sampler, values_from = c(D2_total, rmse_total_pp, skill_total)) %>% filter(!is.na(D2_total_random), !is.na(D2_total_balanced))
  write.csv(fp %>% group_by(env, order, n_sites) %>% summarise(n_pairs = n(), skill_random = median(skill_total_random), skill_balanced = median(skill_total_balanced), skill_diff_median = median(skill_total_balanced - skill_total_random), balanced_better = mean(skill_total_balanced > skill_total_random), rmse_random_pp = median(rmse_total_pp_random), rmse_balanced_pp = median(rmse_total_pp_balanced), .groups = "drop"), file.path(T, sprintf("sim_%s_paired_prediction.csv", SIM)), row.names = FALSE)
  cat(SIM, ": units", nrow(sup) / 2, "| supported fraction by sampler:\n"); print(sup %>% group_by(sampler) %>% summarise(supported = mean(supported))) }
